-- VIP charter passengers for Desert Air Patrol. All names and stories are fiction.
-- who, variant, rule (nil, "hurry" or "nervous"), ask, dest (16 bytes at most; it leads the HUD line), thanks, late (when rule is set).
return {
  {who = "Mr. Silverman", variant = 8, rule = "hurry", ask = "a casino owner late for a board meeting",
   dest = "Board meeting", thanks = "Mr. Silverman tips like a man who just bought a hotel.",
